const sanitizePrescriptionUrls = (input) => {
  if (!input) return [];
  const flat = Array.isArray(input) ? input.flat(Infinity) : [input];
  return flat
    .map((val) => (typeof val === "string" ? val.trim() : (val ? String(val).trim() : "")))
    .filter((val) => val.length > 0 && val !== "[object Object]" && val !== "[]");
};

const formatTime12Hour = (timeStr) => {
  if (!timeStr) return "";
  const str = String(timeStr).trim();
  if (/am|pm/i.test(str)) return str;
  const parts = str.split(":");
  if (parts.length < 2) return str;
  let hours = parseInt(parts[0], 10);
  const minutes = parts[1].slice(0, 2);
  if (isNaN(hours)) return str;
  const ampm = hours >= 12 ? "PM" : "AM";
  hours = hours % 12;
  hours = hours ? hours : 12;
  const formattedHours = String(hours).padStart(2, "0");
  return `${formattedHours}:${minutes} ${ampm}`;
};

const formatTimeTo24Hour = (timeStr) => {
  if (!timeStr) return "";
  const str = String(timeStr).trim();
  // If already "HH:MM" (24hr without AM/PM)
  if (/^\d{1,2}:\d{2}$/.test(str)) {
    const [h, m] = str.split(":");
    return `${String(h).padStart(2, "0")}:${m}`;
  }
  // If "10:00 AM" or "02:30 PM"
  const match = str.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (match) {
    let hours = parseInt(match[1], 10);
    const minutes = match[2];
    const ampm = (match[3] || "").toUpperCase();
    if (ampm === "PM" && hours < 12) hours += 12;
    if (ampm === "AM" && hours === 12) hours = 0;
    return `${String(hours).padStart(2, "0")}:${minutes}`;
  }
  return str;
};

const formatDateDMY = (dateInput) => {
  if (!dateInput) return "N/A";
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) {
    if (typeof dateInput === "string" && /^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(dateInput)) {
      const parts = dateInput.split(/[-/]/);
      return `${parts[2].padStart(2, "0")}/${parts[1].padStart(2, "0")}/${parts[0]}`;
    }
    return String(dateInput);
  }
  const day = String(d.getDate()).padStart(2, "0");
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
};

const CountdownTimer = ({ quotationEndTime, extendedQuotationEndTime, targetDate, fallbackCreatedAt, onExpire }) => {
  const [timerState, setTimerState] = useState({ remaining: 0, isExtended: false });

  useEffect(() => {
    const calculateTimeLeft = () => {
      const nowMs = Date.now();
      let qEndMs = 0;
      const primaryDate = quotationEndTime || targetDate;
      if (primaryDate) {
        qEndMs = new Date(primaryDate).getTime();
      } else if (fallbackCreatedAt) {
        qEndMs = new Date(fallbackCreatedAt).getTime() + 30 * 60 * 1000;
      }

      let extEndMs = 0;
      if (extendedQuotationEndTime) {
        extEndMs = new Date(extendedQuotationEndTime).getTime();
      }

      if (qEndMs > 0 && nowMs < qEndMs) {
        return { remaining: Math.max(0, Math.floor((qEndMs - nowMs) / 1000)), isExtended: false };
      } else if (extEndMs > 0 && nowMs < extEndMs) {
        return { remaining: Math.max(0, Math.floor((extEndMs - nowMs) / 1000)), isExtended: true };
      } else {
        return { remaining: 0, isExtended: false };
      }
    };

    const initial = calculateTimeLeft();
    setTimerState(initial);
    if (initial.remaining <= 0 && onExpire) {
      onExpire();
      return;
    }

    const interval = setInterval(() => {
      const current = calculateTimeLeft();
      setTimerState(current);
      if (current.remaining <= 0) {
        clearInterval(interval);
        if (onExpire) {
          onExpire();
        }
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [quotationEndTime, extendedQuotationEndTime, targetDate, fallbackCreatedAt, onExpire]);

  if (timerState.remaining <= 0) {
    return null;
  }

  const hours = Math.floor(timerState.remaining / 3600);
  const minutes = Math.floor((timerState.remaining % 3600) / 60);
  const seconds = timerState.remaining % 60;

  const formattedTime = hours > 0
    ? `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
    : `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;

  const isExtended = timerState.isExtended;

  return (
    <span
      className="badge d-inline-flex align-items-center gap-1"
      style={{
        backgroundColor: isExtended ? "#FEE2E2" : "#DCFCE7",
        color: isExtended ? "#B91C1C" : "#15803D",
        border: isExtended ? "1px solid #FCA5A5" : "1px solid #86EFAC",
        borderRadius: "6px",
        padding: "4px 8px",
        fontSize: "12px",
        fontWeight: "700"
      }}
    >
      <FiClock size={12} style={{ color: isExtended ? "#B91C1C" : "#15803D" }} />
      {formattedTime}
    </span>
  );
};


